    total = 0
    for year in range(1900, y):
        total += 366 if is_leap(year) else 365
    for month in range(1, m):
        total += MONTH_DAYS[month - 1]
        if month == 2 and is_leap(y):
            total += 1
    return total + d - 1


def main():
    y, m, d = map(int, sys.stdin.read().split())
    diff = days_since_1900(y, m, d) - days_since_1900(2000, 1, 1)
    # 星期六的編號是 5（星期一 = 0）
