// 精確的整數平方根：回傳最大的 r 使得 r*r <= n
ll isqrtExact(ll n) {
    ll r = (ll)sqrtl((long double)n);
    while ((__int128)r * r > n)
        r--;
    while ((__int128)(r + 1) * (r + 1) <= n)
        r++;
    return r;
}

