import sys
from math import isqrt


def main():
    L, R = map(int, sys.stdin.read().split())
    size = R - L + 1
    is_prime = [True] * size          # is_prime[i] 代表 L+i 是否仍可能是質數
    for i in range(size):
        if L + i < 2:
            is_prime[i] = False       # 1 與以下不是質數
    limit = isqrt(R)
    # 先用小篩法求出 2..sqrt(R) 的質數
    small = bytearray([1]) * (limit + 1)
    for p in range(2, limit + 1):
        if small[p]:
            for q in range(p * p, limit + 1, p):
                small[q] = 0
            # 把區間內 p 的倍數劃掉（從 max(p*p, 第一個 >=L 的倍數) 開始）
            start = max(p * p, (L + p - 1) // p * p)
            for m in range(start, R + 1, p):
                is_prime[m - L] = False
    print(sum(is_prime))


main()

