    cin >> L >> R;
    ll size = R - L + 1;
    vector<char> isPrime(size, 1);
    for (ll i = 0; i < size; i++)
        if (L + i < 2) isPrime[i] = 0;
    ll limit = (ll)sqrtl((long double)R);
    while (limit * limit > R) limit--;
    while ((limit + 1) * (limit + 1) <= R) limit++;
    vector<char> small(limit + 1, 1);
    for (ll p = 2; p <= limit; p++) {
        if (!small[p]) continue;
        for (ll q = p * p; q <= limit; q += p) small[q] = 0;
        ll start = max(p * p, (L + p - 1) / p * p);
        for (ll m = start; m <= R; m += p) isPrime[m - L] = 0;
    }
    ll cnt = 0;
    for (ll i = 0; i < size; i++) cnt += isPrime[i];
    cout << cnt << '\n';
    return 0;
}

