#include <bits/stdc++.h>
using namespace std;

bool isLeap(int y) { return (y % 4 == 0 && y % 100 != 0) || y % 400 == 0; }

int daysInMonth(int y, int m) {
    if (m == 2) return isLeap(y) ? 29 : 28;
    if (m == 4 || m == 6 || m == 9 || m == 11) return 30;
    return 31;
}

int main() {
    long long y, m, d, k;
    cin >> y >> m >> d >> k;
    while (k > 0) {
        long long left = daysInMonth(y, m) - d;
        if (k <= left) {
            d += k;
            k = 0;
        } else {
            k -= left + 1;
            d = 1;
            m++;
            if (m == 13) { m = 1; y++; }
        }
    }
    printf("%04lld-%02lld-%02lld\n", y, m, d);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int val(char c) { return isdigit((unsigned char)c) ? c - '0' : c - 'A' + 10; }

int main() {
    int b;
    string x, y;
    cin >> b >> x >> y;
    const string DIGITS = "0123456789ABCDEF";
    int i = (int)x.size() - 1, j = (int)y.size() - 1;
    int carry = 0;
    string out;
    while (i >= 0 || j >= 0 || carry) {
        int s = carry;
        if (i >= 0) s += val(x[i--]);
        if (j >= 0) s += val(y[j--]);
        out += DIGITS[s % b];
        carry = s / b;
    }
    reverse(out.begin(), out.end());
    size_t pos = out.find_first_not_of('0');
    if (pos == string::npos) out = "0";
    else out = out.substr(pos);
    cout << out << '\n';
    return 0;
}

#include <bits/stdc++.h>
