typedef long long ll;

int smaller(int d) { return d - (d > 4 ? 1 : 0); }

int main() {
    string s;
    cin >> s;
    int len = s.size();
    vector<ll> pw(len + 1, 1);
    for (int i = 1; i <= len; i++) pw[i] = pw[i - 1] * 9;
    ll total = 0;
    bool has4 = false;
    for (int pos = 0; pos < len; pos++) {
        int d = s[pos] - '0';
        int rest = len - pos - 1;
        total += smaller(d) * pw[rest];
        if (d == 4) { has4 = true; break; }
    }
    if (!has4) total++;
    cout << total - 1 << '\n';
    return 0;
}
